<script setup lang="ts">
import {computed, nextTick, onBeforeUnmount, onMounted, ref, watch} from 'vue'
import {Info, ListChecks, SlidersHorizontal, Copy, ArrowLeft, CircleCheck, AlertCircle} from 'lucide-vue-next'
import {api} from '../lib/api'
import type {ExportManifest, Job, MatterDocument} from '../lib/types'
import '../variant-design.css'

type Baseline={kind:'primary'|'variant';id:string;version:number|null;input_snapshot:string;included_ids:string[];build_id?:string|null;build_sha256?:string|null}
type Settings={max_pages_per_volume:number;keep_groups_intact:boolean;output_marks:Record<string,unknown>}
type Plan={id:string;version:number;name:string;baseline:Baseline;included_ids:string[];sources:Array<{document_id:string;working_revision:number;source_page_count:number;page_ids:string[]}>;settings:Settings;input_snapshot:string}
type Catalog={plans:Plan[];documents:MatterDocument[];source_snapshot:string;primary_baseline:Baseline;primary_settings:Settings;blank_settings:Settings}
type Finding={severity:string;code:string;message:string;document_id?:string|null}
type Review={plan:Plan;contract_digest:string;current:boolean;stale_reason:string;preview:{included_documents:number;source_pages:number;generated_pages:number;combined_pages:number;volumes:Array<{number:number;page_count:number;rows:Array<{title:string;start_page:number;end_page:number;combined_start_page:number;combined_end_page:number}>}>};checks:Finding[];differences:Array<{document_id:string;title:string;state:string;pages:number;revision:number}>;settings_differences:string[];output_history:ExportManifest[]}
const props=defineProps<{matterId:string;artifacts:ExportManifest[];job:Job|null;blocked:boolean;refreshKey:number}>()
const emit=defineEmits<{primary:[];build:[string];review:[string,string];export:[ExportManifest];checks:[ExportManifest];cancelJob:[];retry:[Job];dirtyChanged:[boolean];context:[string]}>()
const catalog=ref<Catalog|null>(null), review=ref<Review|null>(null), loading=ref(true), saving=ref(false), error=ref('')
const selectedId=ref('primary'), mode=ref<'list'|'membership'|'settings'|'map'|'preflight'|'result'>('list')
const name=ref(''), baselineId=ref(''), copySettings=ref(true)
const draftIds=ref<string[]>([]), draftSettings=ref<Settings|null>(null)
const heading=ref<HTMLElement|null>(null)
let caller:HTMLElement|null=null, callerText='', request=0
const storageKey=computed(()=>`matterdraft.activeVariant.${props.matterId}`)
const selected=computed(()=>catalog.value?.plans.find(p=>p.id===selectedId.value)||null)
watch(selected,plan=>emit('context',plan?.name||''),{immediate:true})
const sourceDocs=computed(()=>catalog.value?.documents.filter(d=>!d.archived_at)||[])
const selectedDocs=computed(()=>sourceDocs.value.filter(d=>selected.value?.included_ids.includes(d.id))||[])
const selectedPages=computed(()=>selectedDocs.value.reduce((n,d)=>n+d.page_count,0))
const primaryPages=computed(()=>sourceDocs.value.filter(d=>catalog.value?.primary_baseline.included_ids.includes(d.id)).reduce((n,d)=>n+d.page_count,0))
function baselineLabel(plan:Plan){return plan.baseline.kind==='primary'?'Primary bundle':catalog.value?.plans.find(p=>`${p.id}:${p.version}`===plan.baseline.id)?.name||plan.baseline.id}
const activeBuild=computed(()=>props.job?.kind==='variant-build'&&props.job.target_id===selectedId.value?props.job:null)
const outputHistory=computed(()=>props.artifacts.filter(a=>a.variant_plan_id===selectedId.value))
const latest=computed(()=>outputHistory.value[0]||null)
const draftPages=computed(()=>sourceDocs.value.filter(d=>draftIds.value.includes(d.id)).reduce((n,d)=>n+d.page_count,0))
const dirty=computed(()=>!!selected.value&&(
  mode.value==='membership'&&JSON.stringify(draftIds.value)!==JSON.stringify(selected.value.included_ids)||
  mode.value==='settings'&&JSON.stringify(draftSettings.value)!==JSON.stringify(selected.value.settings)))
watch(dirty,value=>emit('dirtyChanged',value),{immediate:true})
const baselineOptions=computed(()=>catalog.value?[{id:catalog.value.primary_baseline.id,label:'Primary bundle',kind:'primary' as const},...catalog.value.plans.map(p=>({id:`${p.id}:${p.version}`,label:`${p.name} · v${p.version}`,kind:'variant' as const}))]:[])
function cloneSettings(value:Settings):Settings{return JSON.parse(JSON.stringify(value)) as Settings}
function draftFrom(plan:Plan){draftIds.value=[...plan.included_ids];draftSettings.value=cloneSettings(plan.settings)}
async function load(){const id=++request;loading.value=true;error.value='';try{const result=await api<Catalog>(`/matters/${props.matterId}/variants`);if(id!==request)return;catalog.value=result;if(!baselineId.value)baselineId.value=result.primary_baseline.id;const saved=localStorage.getItem(storageKey.value);if(selectedId.value==='primary'&&saved&&result.plans.some(p=>p.id===saved))selectedId.value=saved;if(selectedId.value!=='primary'&&!result.plans.some(p=>p.id===selectedId.value))selectedId.value='primary';if(selected.value)await loadReview(selected.value.id)}catch(e){if(id===request)error.value=e instanceof Error?e.message:String(e)}finally{if(id===request)loading.value=false}}
async function loadReview(id:string){try{review.value=await api<Review>(`/matters/${props.matterId}/variants/${id}/review`)}catch(e){review.value=null;error.value=e instanceof Error?e.message:String(e)}}
function choose(id:string){selectedId.value=id;review.value=null;if(id==='primary')localStorage.removeItem(storageKey.value);else{localStorage.setItem(storageKey.value,id);void loadReview(id)}}
function focusHeading(){void nextTick(()=>heading.value?.focus({preventScroll:true}))}
function enter(next:typeof mode.value){caller=document.activeElement as HTMLElement;callerText=caller?.textContent?.trim()||'';mode.value=next;if(selected.value)draftFrom(selected.value);focusHeading()}
function returnToList(){mode.value='list';void nextTick(()=>{const replacement=Array.from(document.querySelectorAll<HTMLElement>('.variant-workspace button')).find(button=>button.textContent?.trim()===callerText);if(caller?.isConnected)caller.focus();else if(replacement)replacement.focus();else heading.value?.focus()})}
function toggle(id:string){draftIds.value=draftIds.value.includes(id)?draftIds.value.filter(item=>item!==id):[...draftIds.value,id]}
async function savePlan(){if(!catalog.value||!selected.value||!draftSettings.value||saving.value)return false;saving.value=true;error.value='';try{const p=selected.value;await api<Plan>(`/matters/${props.matterId}/variants/${p.id}`,'PUT',{name:p.name,baseline_kind:p.baseline.kind,baseline_id:p.baseline.id,included_ids:draftIds.value,max_pages_per_volume:Number(draftSettings.value.max_pages_per_volume),keep_groups_intact:draftSettings.value.keep_groups_intact,output_marks:draftSettings.value.output_marks,expected_snapshot:catalog.value.source_snapshot,expected_version:p.version});await load();returnToList();return true}catch(e){error.value=e instanceof Error?e.message:String(e);return false}finally{saving.value=false}}
async function create(){if(!catalog.value||saving.value)return;const source=baselineId.value===catalog.value.primary_baseline.id?null:catalog.value.plans.find(p=>`${p.id}:${p.version}`===baselineId.value);const baseline=source?{kind:'variant' as const,id:`${source.id}:${source.version}`}:{kind:'primary' as const,id:catalog.value.primary_baseline.id};const settings=copySettings.value?(source?.settings||catalog.value.primary_settings):catalog.value.blank_settings;const included=copySettings.value?(source?.included_ids||catalog.value.primary_baseline.included_ids):[];saving.value=true;error.value='';try{const plan=await api<Plan>(`/matters/${props.matterId}/variants`,'POST',{name:name.value,baseline_kind:baseline.kind,baseline_id:baseline.id,included_ids:included,max_pages_per_volume:settings.max_pages_per_volume,keep_groups_intact:settings.keep_groups_intact,output_marks:settings.output_marks,expected_snapshot:catalog.value.source_snapshot});selectedId.value=plan.id;localStorage.setItem(storageKey.value,plan.id);name.value='';await load();focusHeading()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{saving.value=false}}
function openSelected(){if(selectedId.value==='primary'){emit('primary');return}enter('map')}
function artifactStatus(plan:Plan){const builds=props.artifacts.filter(a=>a.variant_plan_id===plan.id);if(!builds.length)return 'Not built';return builds[0]?.stale?'Output out of date':`Build ${builds[0]?.id.slice(0,8)}`}
function reportState(){if(!review.value)return 'Review unavailable';if(!review.value.current)return 'Needs review';return review.value.checks.some(c=>c.severity==='error')?'Blocking findings':'Map ready'}
watch(()=>[props.matterId,props.refreshKey],()=>void load(),{immediate:true})
watch(()=>props.job?.status, status=>{if(activeBuild.value&&status==='completed'){mode.value='result';void load()}},{flush:'post'})
onMounted(focusHeading)
onBeforeUnmount(()=>{request++;emit('dirtyChanged',false);emit('context','')})
defineExpose({saveDraft:savePlan,discard:returnToList,openMembership:()=>{if(!selected.value)return false;if(dirty.value)return true;if(mode.value!=='membership')enter('membership');return true}})
</script>
<template>
 <section class="variant-workspace" :data-mode="mode" aria-label="Audience variants" @keydown.esc.stop="mode!=='list'&&returnToList()">
  <header class="variant-heading"><div><h1 ref="heading" tabindex="-1">{{mode==='list'?'Bundle variants':mode==='membership'?'Review membership':mode==='settings'?'Review settings':mode==='map'?'Variant page map':mode==='preflight'?'Variant Preflight':'Variant output'}}</h1><p v-if="mode==='list'">One matter and shared source revisions · Each variant has its own membership, settings and outputs.</p><p v-else>{{selected?.name}} · version {{selected?.version}} · {{selected?.baseline.kind}} baseline</p></div><button v-if="mode==='list'" class="membership-button primary" :disabled="selectedId==='primary'&&blocked" @click="openSelected">Open selected</button><button v-else class="membership-button secondary" @click="returnToList"><ArrowLeft :size="16"/> Back to variants</button></header>
  <div v-if="error" class="variant-error" role="alert">{{error}} <button class="text-tool" @click="load">Reload</button></div>
  <p v-if="loading" role="status">Loading variants…</p>
  <template v-else-if="catalog">
   <div v-if="mode==='list'" class="variant-grid">
    <section class="variant-card variant-saved"><h2>Saved variants</h2><div class="variant-table-scroll"><table><colgroup><col style="width:39%"><col style="width:13%"><col style="width:16%"><col style="width:32%"></colgroup><thead><tr><th>Variant</th><th>Included</th><th>Source pages</th><th>Output</th></tr></thead><tbody><tr :class="{selected:selectedId==='primary'}"><td><button :aria-pressed="selectedId==='primary'" @click="choose('primary')">Primary bundle</button></td><td>{{catalog.primary_baseline.included_ids.length}}</td><td>{{primaryPages}}</td><td>{{artifacts.find(a=>a.artifact_kind==='primary')?.id.slice(0,8)||'Not built'}}</td></tr><tr v-for="plan in catalog.plans" :key="plan.id" :class="{selected:selectedId===plan.id}"><td><button :aria-pressed="selectedId===plan.id" @click="choose(plan.id)">{{plan.name}}</button></td><td>{{plan.included_ids.length}}</td><td>{{sourceDocs.filter(d=>plan.included_ids.includes(d.id)).reduce((n,d)=>n+d.page_count,0)}}</td><td>{{artifactStatus(plan)}}</td></tr></tbody></table></div>
     <div class="variant-selected-detail"><h3>{{selected?.name||'Primary bundle'}}</h3><template v-if="selected"><p>{{selectedDocs.length}} included documents · {{sourceDocs.length-selectedDocs.length}} excluded from this variant<br>{{selectedPages}} source + {{review?.preview.generated_pages??'—'}} generated = {{review?.preview.combined_pages??'—'}} physical pages<br>{{reportState()}} · {{review?.preview.volumes.length??'—'}} volumes · {{outputHistory.length}} independent output{{outputHistory.length===1?'':'s'}}</p><p class="variant-baseline">Baseline: {{baselineLabel(selected)}} · source {{selected.baseline.input_snapshot.slice(0,12)}}<template v-if="selected.baseline.build_id"> · build {{selected.baseline.build_id.slice(0,8)}}</template></p><div class="variant-actions"><button class="membership-button secondary" @click="enter('membership')"><ListChecks :size="16"/> Review membership</button><button class="membership-button secondary" @click="enter('settings')"><SlidersHorizontal :size="16"/> Review settings</button></div><button class="text-tool" @click="enter('preflight')">{{reportState()}} · Review differences and Preflight</button><button v-if="outputHistory.length" class="text-tool" @click="enter('result')">View {{outputHistory.length}} saved output{{outputHistory.length===1?'':'s'}}</button></template><template v-else><p>{{catalog.primary_baseline.included_ids.length}} included documents · {{sourceDocs.length-catalog.primary_baseline.included_ids.length}} reference-only documents<br>Primary settings and output history remain separate.</p><div class="variant-actions"><button class="membership-button secondary" @click="emit('primary')">Open primary bundle</button></div></template><p class="variant-footnote">Selecting a variant changes the working composition for that plan. Imported originals and earlier generated builds remain preserved. Exclusion is not content removal or secure redaction.</p></div>
    </section>
    <section class="variant-card variant-create"><h2>Create a variant</h2><label>Variant name<input v-model.trim="name" maxlength="80" placeholder="e.g. Focused extracts" @keydown.enter.prevent="create"></label><label>Start from<select v-model="baselineId"><option v-for="option in baselineOptions" :key="option.id" :value="option.id">{{option.label}}</option></select></label><label class="variant-checkbox"><input v-model="copySettings" type="checkbox"> Copy membership and settings</label><div class="variant-notice"><strong><Info :size="16"/> Source files are shared</strong><p>Each variant keeps its own output history. Changing inclusion does not duplicate or delete source documents.</p></div><button class="membership-button primary variant-create-button" :disabled="!name||saving||blocked" @click="create"><Copy :size="16"/> {{saving?'Creating…':'Create variant'}}</button><p class="variant-create-note">Variants are preparation plans, not access controls or sharing permissions. Review pending PDF redaction marks separately.</p></section>
   </div>
   <template v-else-if="selected && draftSettings">
    <section v-if="mode==='membership'" class="variant-task-card"><h2>Included documents and pages</h2><p>Apply saves a new version of {{selected.name}}. Cancel returns to the selected variant without changing its plan.</p><div class="variant-member-scroll"><table><thead><tr><th>Include</th><th>Document</th><th>Revision</th><th>Source pages</th><th>Status</th></tr></thead><tbody><tr v-for="doc in sourceDocs" :key="doc.id"><td><input type="checkbox" :aria-label="`Include ${doc.title}`" :checked="draftIds.includes(doc.id)" @change="toggle(doc.id)"></td><td>{{doc.title}}</td><td>r{{doc.revision}}</td><td>{{doc.page_count}}</td><td>{{draftIds.includes(doc.id)?'Included':'Excluded from this variant'}}</td></tr></tbody></table></div><p>{{draftIds.length}} documents · {{draftPages}} source pages. Exclusion retains the imported original and working revisions.</p><div class="variant-task-actions"><button class="membership-button secondary" @click="returnToList">Cancel</button><button class="membership-button primary" :disabled="saving||blocked" @click="savePlan">{{saving?'Applying…':'Apply membership'}}</button></div></section>
    <section v-else-if="mode==='settings'" class="variant-task-card"><h2>Variant output settings</h2><p>These settings belong to {{selected.name}}. The primary bundle and other variants keep their own settings.</p><div class="variant-settings-fields"><label>Maximum physical pages per volume<input v-model.number="draftSettings.max_pages_per_volume" type="number" min="2" max="2000"></label><label class="variant-checkbox"><input v-model="draftSettings.keep_groups_intact" type="checkbox"> Keep groups together</label><label>Front matter<select v-model="draftSettings.output_marks.front_matter"><option value="index_only">Index only</option><option value="cover_index">Cover and index</option></select></label><label>Index density<select v-model="draftSettings.output_marks.index_style"><option value="compact">Compact</option><option value="readable">Readable</option><option value="review">Review</option></select></label><label>Numbering style<select v-model="draftSettings.output_marks.numbering_style"><option value="arabic">Arabic</option><option value="roman_lower">Roman lower</option><option value="roman_upper">Roman upper</option></select></label><label>Numbering start<input v-model.number="draftSettings.output_marks.numbering_start" type="number" min="1"></label></div><p>Other copied output options are retained in the saved snapshot. Review the page map and Preflight after applying.</p><div class="variant-task-actions"><button class="membership-button secondary" @click="returnToList">Cancel</button><button class="membership-button primary" :disabled="saving||blocked" @click="savePlan">{{saving?'Applying…':'Apply settings'}}</button></div></section>
    <section v-else-if="mode==='map'" class="variant-task-card"><h2>Deterministic page map</h2><p>{{review?.preview.source_pages??'—'}} source + {{review?.preview.generated_pages??'—'}} generated = {{review?.preview.combined_pages??'—'}} physical pages · {{review?.preview.volumes.length??'—'}} volumes. All output positions derive from this map.</p><div v-if="!review?.current" class="variant-error" role="alert">{{review?.stale_reason}}</div><div class="variant-member-scroll"><table><thead><tr><th>Volume</th><th>Document</th><th>Volume pages</th><th>Combined pages</th></tr></thead><tbody><template v-for="volume in review?.preview.volumes||[]" :key="volume.number"><tr v-for="row in volume.rows" :key="`${volume.number}-${row.title}-${row.start_page}`"><td>{{volume.number}}</td><td>{{row.title}}</td><td>{{row.start_page}}–{{row.end_page}}</td><td>{{row.combined_start_page}}–{{row.combined_end_page}}</td></tr></template></tbody></table></div><div class="variant-task-actions"><button class="membership-button secondary" @click="returnToList">Back</button><button class="membership-button primary" @click="enter('preflight')">Review Preflight</button></div></section>
    <section v-else-if="mode==='preflight'" class="variant-task-card"><h2>Inclusion differences and Preflight</h2><p>Compared with {{selected.baseline.kind==='primary'?'the saved primary source baseline':'the chosen variant baseline'}}. This is a technical preparation review, not filing approval.</p><div class="variant-difference-grid"><div><h3>Inclusion differences</h3><ul><li v-for="item in review?.differences||[]" :key="item.document_id"><strong>{{item.state}}</strong> {{item.title}} · r{{item.revision}} · {{item.pages}} pages</li></ul><h3>Settings differences</h3><p>{{review?.settings_differences.length?review.settings_differences.join(', '):'No settings differences from baseline'}}</p></div><div><h3>Validation</h3><p v-if="!review?.current" role="alert">{{review?.stale_reason}}</p><ul><li v-for="item in review?.checks||[]" :key="item.code+item.message"><strong>{{item.severity}}</strong> {{item.message}}</li></ul></div></div><div class="variant-task-actions"><button class="membership-button secondary" @click="returnToList">Back</button><button class="membership-button secondary" @click="enter('map')">Page map</button><button class="membership-button primary" :disabled="blocked||!review?.current||!selected.included_ids.length||review?.checks.some(c=>c.severity==='error')" @click="emit('build',selected.id)">Build {{selected.name}}</button></div></section>
    <section v-else-if="mode==='result'" class="variant-task-card"><h2>Independent output history</h2><p>Builds below retain their exact variant version, source revisions, membership, settings and generated bytes.</p><div v-if="activeBuild" class="variant-job" role="status"><CircleCheck v-if="activeBuild.status==='completed'" :size="16"/><AlertCircle v-else :size="16"/> {{activeBuild.status}} · {{activeBuild.message}} <button v-if="['queued','running'].includes(activeBuild.status)" class="text-tool" @click="emit('cancelJob')">Cancel job</button><button v-if="activeBuild.status==='interrupted'" class="text-tool" @click="emit('retry',activeBuild)">Retry</button></div><div class="variant-member-scroll"><table><thead><tr><th>Build</th><th>Plan</th><th>Pages</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="artifact in outputHistory" :key="artifact.id"><td>{{artifact.id.slice(0,8)}}</td><td>v{{artifact.variant_plan_version}}</td><td>{{artifact.pages}}</td><td>{{artifact.stale?'Earlier version':'Current snapshot'}}</td><td><button class="text-tool" @click="emit('checks',artifact)">Checks</button><button class="text-tool" @click="emit('review',artifact.id,'combined.pdf')">Review PDF</button><button class="text-tool" @click="emit('export',artifact)">Export / Save</button></td></tr></tbody></table></div><p v-if="!outputHistory.length">No output has been built for this variant yet.</p><div class="variant-task-actions"><button class="membership-button secondary" @click="returnToList">Back to variants</button><button class="membership-button secondary" @click="enter('preflight')">Review current plan</button></div></section>
   </template>
  </template>
 </section>
</template>
